package com.schwinglive.aerialfishingimprovements;

import javax.inject.Inject;
import java.io.IOException;

import lombok.extern.slf4j.Slf4j;
import net.runelite.client.audio.AudioPlayer;

@Slf4j
public class MolchPearlChimeAudio
{
    public enum Sound
    {
        PING("pluck.wav"),
        RING("ding.wav"),
        TICK("tick.wav"),
        CHIME("chime.wav");

        private final String fileName;

        Sound(String fileName)
        {
            this.fileName = fileName;
        }
    }

    private final AudioPlayer audioPlayer;

    @Inject
    public MolchPearlChimeAudio(AudioPlayer audioPlayer)
    {
        this.audioPlayer = audioPlayer;
    }

    public void play(Sound sound, int volume)
    {
        int percentage = Math.max(0, Math.min(100, volume));
        if (percentage == 0)
        {
            return;
        }

        float gain = (float) (20.0 * Math.log10(percentage / 100.0));
        String path = "/com/schwinglive/aerialfishingimprovements/sounds/" + sound.fileName;
        try
        {
            audioPlayer.play(MolchPearlChimeAudio.class, path, gain);
        }
        catch (Exception e)
        {
            log.warn("Unable to play pearl sound {}", sound, e);
        }
    }
}

package com.schwinglive.aerialfishingimprovements;

import java.awt.Color;

import net.runelite.client.config.Alpha;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Range;

@ConfigGroup("molchpearlchime")
public interface MolchPearlChimeConfig extends Config
{
	// Audio section
	@ConfigSection(
			name = "Audio",
			description = "Configure pearl notification sounds",
			position = 0
	)
	String audioSection = "audioSection";

	@ConfigItem(
			keyName = "enabled",
			name = "Enable sound",
			description = "Play a sound when gaining Molch Pearls",
			section = audioSection,
			position = 0
	)
	default boolean enabled()
	{
		return true;
	}

	@ConfigItem(
			keyName = "sound",
			name = "Sound effect",
			description = "Select the sound played when receiving pearls",
			section = audioSection,
			position = 1
	)
	default PearlSound sound()
	{
		return PearlSound.RING;
	}

	@Range(min = 0, max = 100)
	@ConfigItem(
			keyName = "volume",
			name = "Volume",
			description = "Volume of pearl notification sounds",
			section = audioSection,
			position = 2
	)
	default int volume()
	{
		return 25;
	}

	// Visual section
	@ConfigSection(
			name = "Visual",
			description = "Customize the floating pearl notification",
			position = 1
	)
	String visualSection = "visualSection";



	// Developer section — intended for development builds
	@ConfigSection(
			name = "Developer",
			description = "Development and testing tools",
			position = 2,
			closedByDefault = true
	)
	String developerSection = "developerSection";


	@ConfigItem(
			keyName = "testNotification",
			name = "Test Notification",
			description = "Play the selected sound and preview the floating pearl notification",
			section = developerSection,
			position = 0
	)
	default boolean testNotification()
	{
		return false;
	}

	@ConfigItem(
			keyName = "visualNotification",
			name = "Enable visual notification",
			description = "Display floating text when gaining pearls",
			section = visualSection,
			position = 0
	)
	default boolean visualNotification()
	{
		return true;
	}


	@ConfigItem(
			keyName = "visualFont",
			name = "Font",
			description = "Choose the OSRS font for the floating notification",
			section = visualSection,
			position = 1
	)
	default OSRSFont visualFont()
	{
		return OSRSFont.PLAIN_11;
	}


	@ConfigItem(
			keyName = "visualFontSize",
			name = "Font size",
			description = "Size of the floating notification text",
			section = visualSection,
			position = 2
	)
	@Range(min = 8, max = 32)
	default int visualFontSize()
	{
		return 16;
	}

	@ConfigItem(
			keyName = "riseDistance",
			name = "Rise distance",
			description = "How far the notification travels upward, in pixels",
			section = visualSection,
			position = 3
	)
	@Range(min = 0, max = 100)
	default int riseDistance()
	{
		return 16;
	}

	@ConfigItem(
			keyName = "animationDuration",
			name = "Animation duration",
			description = "Time for the notification to rise and fade, in milliseconds",
			section = visualSection,
			position = 4
	)
	@Range(min = 250, max = 3000)
	default int animationDuration()
	{
		return 1000;
	}

	@ConfigItem(
			keyName = "fadeOut",
			name = "Fade out",
			description = "Gradually fade the notification away",
			section = visualSection,
			position = 5
	)
	default boolean fadeOut()
	{
		return true;
	}

	@Alpha
	@ConfigItem(
			keyName = "textColor",
			name = "Text color",
			description = "Color of the floating notification",
			section = visualSection,
			position = 6
	)
	default Color textColor() {
		return new Color(255, 220, 120);
	}

	enum PearlSound
	{
		PING("Pluck"),
		RING("Ding"),
		TICK("Tick"),
		CHIME("Chime");

		private final String label;

		PearlSound(String label)
		{
			this.label = label;
		}

		@Override
		public String toString()
		{
			return label;
		}
	}


	enum OSRSFont
	{
		QUILL_8("Quill 8", "RuneScape-Quill-8.ttf"),
		BOLD_12("Bold 12", "RuneScape-Bold-12.ttf"),
		PLAIN_11("Plain 11", "RuneScape-Plain-11.ttf"),
		PLAIN_12("Plain 12", "RuneScape-Plain-12.ttf");

		private final String label;
		private final String resourceName;

		OSRSFont(String label, String resourceName)
		{
			this.label = label;
			this.resourceName = resourceName;
		}

		public String getResourceName()
		{
			return resourceName;
		}

		@Override
		public String toString()
		{
			return label;
		}
	}

}

package com.schwinglive.aerialfishingimprovements;

import java.awt.AlphaComposite;
import java.awt.Color;
import java.awt.Font;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.io.IOException;
import java.io.InputStream;
import java.util.EnumMap;
import java.util.Map;

import javax.inject.Inject;

import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.api.Point;
import net.runelite.api.gameval.ItemID;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

@Slf4j
public class MolchPearlChimeOverlay extends Overlay
{
    private static final Color OUTLINE_COLOR = new Color(45, 32, 15);
    private static final int ICON_SIZE = 28;
    private static final int ICON_SPACING = 0;
    private static final int VERTICAL_OFFSET = 35;

    private final Client client;
    private final MolchPearlChimeConfig config;
    private final BufferedImage pearlIcon;

    private final Map<MolchPearlChimeConfig.OSRSFont, Font> fonts =
            new EnumMap<>(MolchPearlChimeConfig.OSRSFont.class);

    private long notificationStartTime;
    private int pearlQuantity;

    @Inject
    public MolchPearlChimeOverlay(
            Client client,
            MolchPearlChimeConfig config,
            ItemManager itemManager)
    {
        this.client = client;
        this.config = config;
        this.pearlIcon = itemManager.getImage(ItemID.AERIAL_FISHING_PEARL);

        loadFonts();

        setPosition(OverlayPosition.DYNAMIC);
        setLayer(OverlayLayer.ABOVE_SCENE);
    }

    private void loadFonts()
    {
        for (MolchPearlChimeConfig.OSRSFont fontChoice
                : MolchPearlChimeConfig.OSRSFont.values())
        {
            String resource = "/fonts/" + fontChoice.getResourceName();

            try (InputStream stream = getClass().getResourceAsStream(resource))
            {
                if (stream == null)
                {
                    log.warn("Font resource not found: {}", resource);
                    continue;
                }

                Font font = Font.createFont(Font.TRUETYPE_FONT, stream);
                fonts.put(fontChoice, font);
            }
            catch (IOException | java.awt.FontFormatException ex)
            {
                log.warn("Unable to load font resource: {}", resource, ex);
            }
        }
    }

    public void showPearls(int quantity)
    {
        if (quantity <= 0)
        {
            return;
        }

        pearlQuantity = quantity;
        notificationStartTime = System.currentTimeMillis();
    }

    @Override
    public java.awt.Dimension render(Graphics2D graphics)
    {
        if (!config.visualNotification() || pearlQuantity <= 0)
        {
            return null;
        }

        long elapsed = System.currentTimeMillis() - notificationStartTime;
        int duration = config.animationDuration();

        if (duration <= 0 || elapsed >= duration)
        {
            pearlQuantity = 0;
            return null;
        }

        Player player = client.getLocalPlayer();

        if (player == null)
        {
            return null;
        }

        float progress = Math.min(1.0f, (float) elapsed / duration);
        int rise = (int) (config.riseDistance() * progress);
        float opacity = config.fadeOut() ? 1.0f - progress : 1.0f;

        String text = "+" + pearlQuantity;

        // Get the player's canvas position and anchor the notification above it.
        Point playerPoint = player.getCanvasTextLocation(
                graphics,
                "",
                player.getLogicalHeight() + VERTICAL_OFFSET
        );

        if (playerPoint == null)
        {
            return null;
        }

        Font baseFont = fonts.get(config.visualFont());

        if (baseFont == null)
        {
            baseFont = new Font(
                    "SansSerif",
                    Font.BOLD,
                    config.visualFontSize()
            );
        }

        Font selectedFont = baseFont.deriveFont(
                (float) config.visualFontSize()
        );

        Graphics2D g = (Graphics2D) graphics.create();

        try
        {
            g.setRenderingHint(
                    RenderingHints.KEY_ANTIALIASING,
                    RenderingHints.VALUE_ANTIALIAS_ON
            );

            g.setComposite(AlphaComposite.getInstance(
                    AlphaComposite.SRC_OVER,
                    Math.max(0.0f, Math.min(1.0f, opacity))
            ));

            g.setFont(selectedFont);

            int textWidth = g.getFontMetrics().stringWidth(text);
            int totalWidth = textWidth + ICON_SPACING + ICON_SIZE;

            // Center the entire text-and-icon group over the player.
            int startX = playerPoint.getX() - totalWidth / 2;
            int textX = startX;
            int iconX = textX + textWidth + ICON_SPACING;
            int y = playerPoint.getY() - rise;

            // Center the icon vertically against the text's visual height.
            int textHeight = g.getFontMetrics().getAscent();
            int iconY = y - (textHeight + ICON_SIZE) / 2;

            if (pearlIcon != null)
            {
                g.drawImage(
                        pearlIcon,
                        iconX,
                        iconY,
                        ICON_SIZE,
                        ICON_SIZE,
                        null
                );
            }

            // Draw the outlined text.
            g.setColor(OUTLINE_COLOR);
            g.drawString(text, textX - 1, y);
            g.drawString(text, textX + 1, y);
            g.drawString(text, textX, y - 1);
            g.drawString(text, textX, y + 1);

            // Draw the main text.
            g.setColor(config.textColor());
            g.drawString(text, textX, y);
        }
        finally
        {
            g.dispose();
        }

        return null;
    }
}

package com.schwinglive.aerialfishingimprovements;

import com.google.inject.Provides;
import javax.inject.Inject;

import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.ItemContainer;
import net.runelite.api.NPC;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.ItemID;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;

@PluginDescriptor(
		name = "Aerial Fishing Improvements",
		description = "Adds configurable audio and visual notifications during Aerial Fishing"
)
public class MolchPearlChimePlugin extends Plugin
{
	private static final int MOLCH_ISLAND_NPC_ID = 8523;

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private MolchPearlChimeConfig config;

	@Inject
	private MolchPearlChimeOverlay pearlOverlay;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private MolchPearlChimeAudio audio;
	private int previousPearlCount;
	private boolean aerialFishing;

	@Provides
	MolchPearlChimeConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(MolchPearlChimeConfig.class);
	}

	@Override
	protected void startUp()
	{
		previousPearlCount = 0;
		aerialFishing = false;
		overlayManager.add(pearlOverlay);
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(pearlOverlay);

		previousPearlCount = 0;
		aerialFishing = false;
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		if (client.getGameState() != GameState.LOGGED_IN)
		{
			setActivity(false);
			previousPearlCount = 0;
			return;
		}

		boolean foundMolchNpc = false;
		for (NPC npc : client.getNpcs())
		{
			if (npc.getId() == MOLCH_ISLAND_NPC_ID)
			{
				foundMolchNpc = true;
				break;
			}
		}

		setActivity(foundMolchNpc);
	}

	private void setActivity(boolean active)
	{
		if (active == aerialFishing)
		{
			return;
		}

		aerialFishing = active;
		if (active)
		{
			// Establish a baseline so existing pearls are not counted as gains.
			previousPearlCount = getInventoryPearlCount();
		}
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event)
	{
		if (event.getContainerId() != InventoryID.INV
				|| client.getGameState() != GameState.LOGGED_IN)
		{
			return;
		}

		ItemContainer container = event.getItemContainer();
		if (container == null)
		{
			return;
		}

		int currentPearlCount = Math.max(0, container.count(ItemID.AERIAL_FISHING_PEARL));
		if (!aerialFishing)
		{
			previousPearlCount = currentPearlCount;
			return;
		}

		if (currentPearlCount < previousPearlCount)
		{
			previousPearlCount = currentPearlCount;
			return;
		}

		int gained = currentPearlCount - previousPearlCount;
		previousPearlCount = currentPearlCount;
		if (gained <= 0)
		{
			return;
		}

		pearlOverlay.showPearls(gained);
		playPearlSound();
	}

	private int getInventoryPearlCount()
	{
		ItemContainer inventory = client.getItemContainer(InventoryID.INV);
		if (inventory == null)
		{
			return 0;
		}

		return Math.max(0, inventory.count(ItemID.AERIAL_FISHING_PEARL));
	}

	private void playPearlSound()
	{
		if (!config.enabled() || config.volume() <= 0 || audio == null)
		{
			return;
		}

		MolchPearlChimeAudio.Sound sound;
		switch (config.sound())
		{
			case PING:
				sound = MolchPearlChimeAudio.Sound.PING;
				break;
			case RING:
				sound = MolchPearlChimeAudio.Sound.RING;
				break;
			case TICK:
				sound = MolchPearlChimeAudio.Sound.TICK;
				break;
			case CHIME:
			default:
				sound = MolchPearlChimeAudio.Sound.CHIME;
				break;
		}

		audio.play(sound, config.volume());
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (!"molchpearlchime".equals(event.getGroup()))
		{
			return;
		}

		if ("testNotification".equals(event.getKey()) && config.testNotification())
		{
			clientThread.invokeLater(() ->
			{
				if (client.getGameState() == GameState.LOGGED_IN)
				{
					pearlOverlay.showPearls(1);
					playPearlSound();
				}
			});
		}
	}
}

